-- Supabase Dashboard > SQL Editor > New query > paste and Run
create extension if not exists pgcrypto;
create table if not exists public.clients(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,industry text,website text,notes text,created_at timestamptz not null default now());
create table if not exists public.content_posts(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,client_id uuid not null references public.clients(id) on delete cascade,title text not null,caption text not null default '',platform text not null check(platform in ('instagram','facebook','youtube','google_business')),content_type text not null default 'post',goal text not null default 'engagement',hashtags text[] not null default '{}',status text not null default 'draft' check(status in ('draft','review','approved','scheduled','published','failed')),scheduled_at timestamptz,published_at timestamptz,created_at timestamptz not null default now());
alter table public.clients enable row level security; alter table public.content_posts enable row level security;
drop policy if exists "Users manage their own clients" on public.clients; create policy "Users manage their own clients" on public.clients for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
drop policy if exists "Users manage their own content" on public.content_posts; create policy "Users manage their own content" on public.content_posts for all using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create index if not exists clients_owner_id_idx on public.clients(owner_id); create index if not exists posts_owner_id_idx on public.content_posts(owner_id); create index if not exists posts_client_id_idx on public.content_posts(client_id);